item.command:
/usr/bin/zsh -lc "cat > candidate.sv <<'EOF'
module TopModule (
    input  logic [2:0] vec,
    output logic [2:0] outv,
    output logic o2,
    output logic o1,
    output logic o0
);
    assign outv = vec;
    assign o2 = vec[2];
    assign o1 = vec[1];
    assign o0 = vec[0];
endmodule
EOF
cp candidate.sv candidate_initial.sv
cat > dev_tb.sv <<'EOF'
"'`timescale 1ns/1ps
module dev_tb;
    logic [2:0] vec;
    wire [2:0] outv;
    wire o2, o1, o0;
    TopModule dut (.vec(vec), .outv(outv), .o2(o2), .o1(o1), .o0(o0));
    initial begin
        for (integer i = 0; i < 8; i = i + 1) begin
            vec = 3'"'(i);
            #1;
            if (outv "'!== vec || {o2, o1, o0} !== vec)
                $fatal(1, "FAIL: vec=%b outv=%b split=%b", vec, outv, {o2,o1,o0});
        end
        $display("PASS: all eight input vectors");
        $finish;
    end
    initial begin
        #100;
        $fatal(1, "FAIL: timeout");
    end
endmodule
EOF
timeout 20s /home/shmin/nl2hdl/.conda_pkgs/iverilog-12.0-ha738cfc_1/bin/iverilog -g2012 -Wall -s dev_tb -o dev_sim candidate.sv dev_tb.sv > compile.log 2>&1
'

